class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
  }

  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move the key to the end (mark as most recently used)
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);

    return value;
  }

  set(key, value) {
    // If key already exists, update it and move to end
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.capacity) {
      // Remove the least recently used item (first item in Map)
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }

    // Add the new key-value pair
    this.cache.set(key, value);
  }
}

module.exports = { LRUCache };

const { LRUCache } = require('./s5_cache.js');

// Test 1: Basic get/set functionality
console.log("Test 1: Basic get/set functionality");
const cache = new LRUCache(2);

cache.set('a', 1);
cache.set('b', 2);
console.assert(cache.get('a') === 1, "get('a') should return 1");
console.assert(cache.get('b') === 2, "get('b') should return 2");
console.log("✓ Basic get/set works");

// Test 2: Capacity limit
console.log("Test 2: Capacity limit");
cache.set('c', 3);
console.assert(cache.get('a') === undefined, "get('a') should be undefined after capacity exceeded");
console.assert(cache.get('b') === 2, "get('b') should still return 2");
console.assert(cache.get('c') === 3, "get('c') should return 3");
console.log("✓ Capacity limit works");

// Test 3: LRU eviction
console.log("Test 3: LRU eviction");
const cache2 = new LRUCache(3);
cache2.set('a', 1);
cache2.set('b', 2);
cache2.set('c', 3);
cache2.get('a'); // Access 'a' to make it most recently used
cache2.set('d', 4); // This should evict 'b' (least recently used)
console.assert(cache2.get('a') === 1, "get('a') should still return 1");
console.assert(cache2.get('b') === undefined, "get('b') should be undefined after eviction");
console.assert(cache2.get('c') === 3, "get('c') should still return 3");
console.assert(cache2.get('d') === 4, "get('d') should return 4");
console.log("✓ LRU eviction works");

// Test 4: Update existing key
console.log("Test 4: Update existing key");
const cache3 = new LRUCache(2);
cache3.set('a', 1);
cache3.set('b', 2);
cache3.set('a', 10); // Update existing key
console.assert(cache3.get('a') === 10, "get('a') should return updated value 10");
console.assert(cache3.get('b') === 2, "get('b') should still return 2");
console.log("✓ Update existing key works");

// Test 5: Get non-existent key
console.log("Test 5: Get non-existent key");
const cache4 = new LRUCache(2);
console.assert(cache4.get('nonexistent') === undefined, "get('nonexistent') should return undefined");
console.log("✓ Get non-existent key works");

console.log("All tests passed!");

